steps = [
    step("Flask 的模板环境:app.jinja_env 的类型是 flask.templating.Environment,它的 loader 是 DispatchingJinjaLoader(分发加载器,去问应用和各蓝图的加载器);app.jinja_loader 是 FileSystemLoader,searchpath 是 <项目>/templates。默认选项(非 debug):autoescape 是 select_jinja_autoescape(按文件名决定)、auto_reload = False、编译缓存 cache_size = 400、trim_blocks 与 lstrip_blocks 为 False、undefined = Undefined;app.jinja_options 是空字典。", t=tl(S(1)), done=lidx(S(1), 'app.jinja_env 类型', 'app.jinja_loader'), mark=lidx(S(1), 'jinja_env 的默认选项', 'jinja_options'), kv=KV([['loader', 'DispatchingJinjaLoader'], ['jinja_loader', 'FileSystemLoader(templates/)'], ['缓存', 'cache_size = 400'], ['auto_reload', 'False(非 debug)']], ['loader'])),
    step("加载器的核心方法是 get_source(env, name),返回 (源码, 文件名, uptodate 函数):hello.html 的源码是 'Hello {{ name }}!\\n',uptodate() 为 True;往文件里追加一个字符后 uptodate() 变成 False,表示缓存的编译结果已经过期。找不到模板时抛 TemplateNotFound: nope.html。", t=tl(S(2)), done=lidx(S(2), '源码 =', '文件被修改后'), mark=lidx(S(2), '找不到'), kv=KV([['get_source', '(源码, 文件名, uptodate)'], ['文件改动后', 'uptodate() = False'], ['不存在', 'TemplateNotFound']], ['uptodate'])),
    step("内置加载器组合(独立的 Environment):DictLoader 从字典读;ChoiceLoader 按顺序尝试多个加载器(字典里的 a.html 覆盖目录里的,hello.html 落到目录);PrefixLoader 按前缀分发(ui/btn.html → <button>,mail/btn.html → 邮件按钮);FunctionLoader 调用一个函数返回源码(dyn/x → 来自函数:dyn/x,调用记录 ['dyn/x'])。", t=tl(S(3)), done=lidx(S(3), 'DictLoader', 'ChoiceLoader', 'PrefixLoader', 'FunctionLoader'), kv=KV([['DictLoader', '字典'], ['ChoiceLoader', '按顺序回退'], ['PrefixLoader', '按前缀分发'], ['FunctionLoader', '函数返回源码']], ['ChoiceLoader'])),
    step("在 Flask 里换自己的加载器:app2.jinja_loader = ChoiceLoader([DictLoader({'hello.html': '被覆盖:{{ name }}'}), 原来的 FileSystemLoader]),GET /h 得到「被覆盖:ann」(字典里的 hello.html 优先),GET /p(page.html 继承 base.html,目录里的)仍然正常得到 <html><p>ann</p></html>。", t=tl(S(4)), done=lidx(S(4), 'GET /h'), kv=KV([['字典里的 hello.html', '覆盖目录里的'], ['其它模板', '落到原来的目录']], ['字典里的 hello.html'])),
    step("模板被编译成 Python 生成器函数:env.compile('Hello {{ name }}!{% for i in items %}[{{ i|upper }}]{% endfor %}', raw=True) 的输出是 def root(context, missing=missing, environment=environment):,里面先用 resolve('name') 解析变量,再按顺序 yield 'Hello '、yield escape(...)、yield '!',for 循环里用 environment.filters['upper'] 取过滤器。渲染就是把这个生成器 yield 出来的字符串拼起来。", t=tl(S(5)), done=lidx(S(5), 'def root(context', "yield 'Hello '"), mark=lidx(S(5), 'escape(', "environment.filters['upper']"), kv=KV([['入口', 'def root(context, …)'], ['输出', 'yield 字符串片段'], ['变量', 'resolve(\"name\") + escape(...)']], ['入口'])),
    step(f"各阶段耗时(一个 51 行的模板:50 行各含一个过滤器与一个条件,再加一个 20 行的循环):parse(只生成语法树){ct[0]:.2f} ms;compile(含代码生成与 Python 编译){ct[1]:.2f} ms;已编译后 render {ct[2]:.3f} ms。编译约是渲染的 {ct[1] / ct[2]:.0f} 倍,所以 Jinja 把编译结果缓存起来(见第 63 篇)。", t=tl(S(6)), b=bars([['parse', ct[0], f'{ct[0]:.2f} ms'], ['compile', ct[1], f'{ct[1]:.2f} ms'], ['render(已编译)', ct[2], f'{ct[2]:.3f} ms']], ct[1], done=[0, 1, 2]), kv=KV([['compile', f'{ct[1]:.2f} ms'], ['render', f'{ct[2]:.3f} ms'], ['倍数', f'≈{ct[1] / ct[2]:.0f}']], ['倍数'])),
]
